ngs":{"category":"luxury_collectibles","tags":"watches, Los Angeles, physical_goods, testnet-beta"},"publishedBlocks":[{"id":"P100-overview-heading","type":"heading","content":"Marketplace Role"},{"id":"P100-overview","type":"paragraph","content":"Los Angeles Time Shop operates as a watch and collectible storefront based in Los Angeles. The profile is seeded for beta testing with realistic storefront context, address metadata, and map-ready coordinates."},{"id":"P100-capability-heading","type":"heading","content":"Capability"},{"id":"P100-capability","type":"paragraph","content":"Focus area: Luxury & Collectibles / Watches. Typical work includes curated product presentation, buyer-ready metadata, repeat listing operations, and marketplace search coverage."},{"id":"P100-trust-heading","type":"heading","content":"Trust Notes"},{"id":"P100-trust","type":"paragraph","content":"Seed profile for v3.5 beta. KYC is not submitted, verified badge is false, and reputation values are synthetic testnet context only."}],"publishedSettings":{"category":"luxury_collectibles","tags":"watches, Los Angeles, physical_goods, testnet-beta"},"seedProfileMetadata":{"seed_source":"orina_v3_5_beta_seed_profiles","seed_batch":"v3.5-beta-seed-profiles-001","source_profile_id":"P100","profile_index":100,"wallet_address":"0x3931d00663e24b20d7a8ec3bd1917ca7efc85f5c","network":"BSC Testnet (97)","asset_class":"physical_goods","primary_category":"luxury_collectibles","subcategory_focus":"watches","category_label":"Luxury & Collectibles","subcategory_label":"Watches","business_type":"watch and collectible storefront","location_label":"Los Angeles","city":"Los Angeles","country":"United States","address":"Rodeo Drive, Beverly Hills","coordinates":{"longitude":-118.4004,"latitude":34.0696},"testnet":true,"beta_seed":true,"verified":false,"kyc_status":"not_submitted","map_visible":true,"synthetic_reputation":{"rating":4.34,"reviews":14,"completed_orders":38}},"updatedAt":1780644662443,"publishedAt":1780644662443},"seed_profile_metadata":{"seed_source":"orina_v3_5_beta_seed_profiles","seed_batch":"v3.5-beta-seed-profiles-001","source_profile_id":"P100","profile_index":100,"wallet_address":"0x3931d00663e24b20d7a8ec3bd1917ca7efc85f5c","network":"BSC Testnet (97)","asset_class":"physical_goods","primary_category":"luxury_collectibles","subcategory_focus":"watches","category_label":"Luxury & Collectibles","subcategory_label":"Watches","business_type":"watch and collectible storefront","location_label":"Los Angeles","city":"Los Angeles","country":"United States","address":"Rodeo Drive, Beverly Hills","coordinates":{"longitude":-118.4004,"latitude":34.0696},"testnet":true,"beta_seed":true,"verified":false,"kyc_status":"not_submitted","map_visible":true,"synthetic_reputation":{"rating":4.34,"reviews":14,"completed_orders":38}}}]$seed$::jsonb;
begin
  create temporary table tmp_v35_seed_profiles (
    row_index integer generated always as identity,
    wallet_address text not null,
    display_name text not null,
    username text not null,
    bio text not null,
    avatar_url text not null,
    banner_url text not null,
    website text null,
    is_verified boolean not null,
    status text not null,
    address text not null,
    city text not null,
    longitude numeric not null,
    latitude numeric not null,
    story_document jsonb not null,
    seed_profile_metadata jsonb not null
  ) on commit drop;

  insert into tmp_v35_seed_profiles (
    wallet_address,
    display_name,
    username,
    bio,
    avatar_url,
    banner_url,
    website,
    is_verified,
    status,
    address,
    city,
    longitude,
    latitude,
    story_document,
    seed_profile_metadata
  )
  select
    lower(trim(item ->> 'wallet_address')),
    item ->> 'display_name',
    item ->> 'username',
    item ->> 'bio',
    item ->> 'avatar_url',
    item ->> 'banner_url',
    nullif(item ->> 'website', ''),
    coalesce((item ->> 'is_verified')::boolean, false),
    coalesce(nullif(item ->> 'status', ''), 'active'),
    item ->> 'address',
    item ->> 'city',
    (item ->> 'longitude')::numeric,
    (item ->> 'latitude')::numeric,
    coalesce(item -> 'story_document', '{}'::jsonb),
    coalesce(item -> 'seed_profile_metadata', '{}'::jsonb)
  from jsonb_array_elements(payload) item;

  insert into public.profiles (
    wallet_address,
    display_name,
    username,
    bio,
    avatar_url,
    banner_url,
    website,
    is_verified,
    status,
    address,
    city,
    coordinates
  )
  select
    wallet_address,
    display_name,
    username::citext,
    bio,
    avatar_url,
    banner_url,
    website,
    is_verified,
    status,
    address,
    city,
    st_setsrid(st_makepoint(longitude, latitude), 4326)
  from tmp_v35_seed_profiles
  on conflict (wallet_address) do update set
    display_name = excluded.display_name,
    username = excluded.username,
    bio = excluded.bio,
    avatar_url = excluded.avatar_url,
    banner_url = excluded.banner_url,
    website = excluded.website,
    is_verified = false,
    status = 'active',
    address = excluded.address,
    city = excluded.city,
    coordinates = excluded.coordinates,
    updated_at = now();

  insert into public.profile_story_documents (user_id, story_document)
  select
    profiles.id,
    seed.story_document
  from tmp_v35_seed_profiles seed
  join public.profiles profiles
    on profiles.wallet_address = seed.wallet_address
  on conflict (user_id) do update set
    story_document = excluded.story_document,
    updated_at = now();

  insert into public.user_preferences (
    user_id,
    notification_settings,
    ui_preferences,
    privacy_settings
  )
  select
    profiles.id,
    '{}'::jsonb,
    jsonb_build_object(
      'seed_profile_metadata',
      seed.seed_profile_metadata,
      'story_document',
      seed.story_document
    ),
    '{}'::jsonb
  from tmp_v35_seed_profiles seed
  join public.profiles profiles
    on profiles.wallet_address = seed.wallet_address
  on conflict (user_id) do update set
    ui_preferences = coalesce(public.user_preferences.ui_preferences, '{}'::jsonb)
      || jsonb_build_object(
        'seed_profile_metadata',
        excluded.ui_preferences -> 'seed_profile_metadata',
        'story_document',
        excluded.ui_preferences -> 'story_document'
      ),
    updated_at = now();

  perform public.refresh_marketplace_profile_browse_index_v1();
end $$;
